import random as _r
from functools import lru_cache as _lc
_L = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]
def _win(b):
    for a, c, d in _L:
        if b[a] != '.' and b[a] == b[c] == b[d]:
            return b[a]
    return None
@_lc(maxsize=None)
def _v(b, p):
    w = _win(b)
    if w:
        return 1 if w == 'X' else -1
    if '.' not in b:
        return 0
    vs = [_v(b[:i] + p + b[i + 1:], 'O' if p == 'X' else 'X') for i in range(9) if b[i] == '.']
    return max(vs) if p == 'X' else min(vs)
def _after(b, i):
    p = 'X' if b.count('X') == b.count('O') else 'O'
    return _v(b[:i] + p + b[i + 1:], 'O' if p == 'X' else 'X')
def _play(seed, agent_first):
    rng, b, agent = _r.Random(seed), '.' * 9, agent_first
    while not _win(b) and '.' in b:
        p = 'X' if b.count('X') == b.count('O') else 'O'
        i = best_move(b) if agent else rng.choice([j for j in range(9) if b[j] == '.'])
        b = b[:i] + p + b[i + 1:]
        agent = not agent
    w = _win(b)
    me = 'X' if agent_first else 'O'
    return 'D' if w is None else ('W' if w == me else 'L')
